  ns.tprint(`Agility: ${player.agility}`);
  ns.tprint(`Charisma: ${player.charisma}`);
  ns.tprint(`Intelligence: ${player.intelligence}`);

  // Check if augmentations can be purchased
  const augList = ns.singularity.getAugmentationsFromFaction("Tian Di Hui");

  ns.tprint(`\n=== Available Augmentations ===");
  for (const aug of augList) {
