    if (stats.hacking_grow_mult) ns.tprint(`  → Grow: x${stats.hacking_grow_mult}`);
    if (stats.hacking_chance_mult) ns.tprint(`  → Chance: x${stats.hacking_chance_mult}`);
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const stocks = ['APPL', 'MSFT', 'GOOGL', 'AMZN', 'TSLA'];
  const portfolio = {};
  let cash = 100000;

  while (true) {
    for (const stock of stocks) {
      try {
        const price = ns.stock.getPrice(stock);
        const vol = ns.stock.getVolatility(stock);
        const ask = ns.stock.getAskPrice(stock);
        const bid = ns.stock.getBidPrice(stock);

        if (!portfolio[stock]) portfolio[stock] = 0;

        const spread = ask - bid;
        if (spread > price * 0.01 && cash > ask * 10) {
          const shares = Math.floor(Math.min(cash / ask, 100));
          ns.stock.buy(stock, shares);
          portfolio[stock] += shares;
          cash -= shares * ask;
        }

        if (portfolio[stock] > 0 && bid > ask * 1.02) {
          ns.stock.sell(stock, portfolio[stock]);
          cash += portfolio[stock] * bid;
          portfolio[stock] = 0;
        }
      } catch (e) {}
    }

    await ns.sleep(5000);
  }
}

