/** @param {NS} ns */
export async function main(ns) {
  const player = ns.getPlayer();
  const home = ns.getServer('home');

  ns.tprint('=== UPGRADE ANALYSIS ===');
  ns.tprint(`Money available: $${ns.formatNumber(player.money)}`);
  ns.tprint(`Hacking level: ${player.hacking}`);
  ns.tprint(`Strength: ${player.strength}`);
  ns.tprint(`Defense: ${player.defense}`);
  ns.tprint(`Dexterity: ${player.dexterity}`);
  ns.tprint(`Agility: ${player.agility}`);
  ns.tprint(`Charisma: ${player.charisma}`);
  ns.tprint(`Intelligence: ${player.intelligence}`);
  ns.tprint('');

  const augmentations = ns.purchasableAugmentations();
  ns.tprint(`Available augmentations: ${augmentations.length}`);

  const hackUpgrades = [];
  const growUpgrades = [];
  const weakenUpgrades = [];
  const otherUpgrades = [];

  for (const aug of augmentations) {
    const cost = ns.getAugmentationCost(aug);
    if (cost > player.money) continue;

    const name = aug.toLowerCase();
    if (name.includes('hack') || name.includes('exploit') || name.includes('neural')) {
      hackUpgrades.push({aug, cost});
    } else if (name.includes('grow') || name.includes('metabolism')) {
      growUpgrades.push({aug, cost});
    } else if (name.includes('weaken') || name.includes('combat')) {
      weakenUpgrades.push({aug, cost});
    } else {
      otherUpgrades.push({aug, cost});
    }
  }

  ns.tprint('\n=== RECOMMENDED UPGRADES (Affordable) ===');
  if (hackUpgrades.length > 0) {
    ns.tprint('Hack Efficiency:');
    for (const {aug, cost} of hackUpgrades.slice(0, 3)) {
      ns.tprint(`  - ${aug}: $${ns.formatNumber(cost)}`);
    }
  }

  if (growUpgrades.length > 0) {
    ns.tprint('Grow Efficiency:');
    for (const {aug, cost} of growUpgrades.slice(0, 3)) {
      ns.tprint(`  - ${aug}: $${ns.formatNumber(cost)}`);
    }
  }

  if (weakenUpgrades.length > 0) {
    ns.tprint('Weaken Efficiency:');
    for (const {aug, cost} of weakenUpgrades.slice(0, 3)) {
      ns.tprint(`  - ${aug}: $${ns.formatNumber(cost)}`);
    }
  }

  if (otherUpgrades.length > 0) {
    ns.tprint('Other:');
    for (const {aug, cost} of otherUpgrades.slice(0, 3)) {
      ns.tprint(`  - ${aug}: $${ns.formatNumber(cost)}`);
    }
  }
}

